// C program for the function called poly_get_coef_by_power
// Contains target function implementation and dependency signatures

#include <stdio.h>  // for io operations
#include <stdlib.h>

struct term
{
    int coef;          /**< coefficient value */
    int pow;           /**< power of the polynomial term */
    struct term *next; /**< pointer to the successive term */
};

// Target function implementation
int poly_get_coef_by_power(struct term *poly, int power, int *found)
{
    if (found != NULL)
    {
        *found = 0;
    }

    while (poly != NULL)
    {
        if (poly->pow == power)
        {
            if (found != NULL)
            {
                *found = 1;
            }
            return poly->coef;
        }
        poly = poly->next;
    }
    return 0;
}

